WITH matched_keys AS (SELECT session_id, id FROM web_events EXCEPT SELECT session_id, id FROM web_events WHERE HOUR(event_time) BETWEEN 7 AND 14), kept_rows AS (SELECT s.* FROM web_events s INNER JOIN matched_keys k ON s.session_id = k.session_id AND s.id = k.id) SELECT DATE_TRUNC('QUARTER', event_time) AS quarter_start, session_id, DATE_TRUNC('YEAR', event_time) AS year_start, STDDEV_SAMP(duration_sec) AS duration_sec_stddev, MIN(duration_sec) AS min_duration_sec, COUNT(CASE WHEN page = '/checkout' THEN 1 END) AS checkout_count FROM kept_rows GROUP BY ROLLUP (DATE_TRUNC('QUARTER', event_time), session_id, DATE_TRUNC('YEAR', event_time)) ORDER BY year_start DESC
